import {
  Bot,
  X,
  Send,
  Mic,
  MicOff,
  Sparkles,
  RotateCcw,
  ChevronRight,
  Loader2,
  GripVertical,
  Volume2,
  VolumeX,
  Download,
} from "lucide-react";

import { cn } from "@/lib/utils";

import { useProject } from "@/contexts/ProjectContext";

import {
  useTickets,
  useBlockers,
  useDevelopers,
  useCurrentSprint,
  useSprintKpis,
} from "@/hooks/useSprintData";

import { useAssistant } from "@/hooks/useAssistant";

import type { UIDeveloper } from "@/services/api/types";

