// Types
// ─────────────────────────────────────────────────────────────────────────────

interface Message {
  id: string;
  role: "user" | "assistant";
  content: string;
  ts: number;
}

// ─────────────────────────────────────────────────────────────────────────────
// Markdown-lite renderer
// ─────────────────────────────────────────────────────────────────────────────

function renderMarkdown(text: string): React.ReactNode[] {
  const lines = text.split("\n");

  return lines.map((line, i) => {
    // Bold: **text**
    const boldParts = line.split(/\*\*(.*?)\*\*/g);

    const boldProcessed = boldParts.map((part, j) =>
      j % 2 === 1 ? (
        <strong
          key={`bold-${j}`}
          className="font-semibold text-foreground"
        >
          {part}
        </strong>
      ) : (
        part
      )
    );

    // Italic: _text_
    const processed = boldProcessed.flatMap((part, j) => {
      if (typeof part !== "string") {
        return [part];
      }

      return part.split(/_(.*?)_/g).map((p, k) =>
        k % 2 === 1 ? (
          <em key={`italic-${j}-${k}`} className="italic">
            {p}
          </em>
        ) : (
          p
        )
      );
    });

    return (
      <span key={i} className="block leading-relaxed">
        {processed}

        {i < lines.length - 1 &&
          !line.startsWith("•") &&
          !line.startsWith("#") &&
          "\u00A0"}
      </span>
    );
  });
}

