// ─────────────────────────────────────────────────────────────────────────────
// Voice input hook
// ─────────────────────────────────────────────────────────────────────────────

function useVoiceInput(onResult: (text: string) => void) {
  const [isListening, setIsListening] = useState(false);

  const recognitionRef = useRef<SpeechRecognition | null>(null);

  const start = useCallback(() => {
    const browserWindow = window as Window & {
      SpeechRecognition?: typeof SpeechRecognition;
      webkitSpeechRecognition?: typeof SpeechRecognition;
    };

    const SR =
      browserWindow.SpeechRecognition ??
      browserWindow.webkitSpeechRecognition;

    if (!SR) {
      alert("Speech recognition is not supported in this browser.");
      return;
    }

    const rec = new SR();

    rec.lang = "en-US";
    rec.interimResults = false;
    rec.maxAlternatives = 1;

    rec.onresult = (e: SpeechRecognitionEvent) => {
      const text = e.results[0][0].transcript;

      if (text.trim()) {
        onResult(text);
      }
    };

    rec.onerror = () => {
      setIsListening(false);
    };

    rec.onend = () => {
      setIsListening(false);
    };

    recognitionRef.current = rec;

    try {
      rec.start();
      setIsListening(true);
    } catch {
      setIsListening(false);
    }
  }, [onResult]);

  const stop = useCallback(() => {
    try {
      recognitionRef.current?.stop();
    } catch {
      // Ignore browser SpeechRecognition stop errors.
    }

    setIsListening(false);
  }, []);

  const toggle = useCallback(() => {
    if (isListening) {
      stop();
    } else {
      start();
    }
  }, [isListening, stop, start]);

  const supported = useMemo(() => {
    const browserWindow = window as Window & {
      SpeechRecognition?: unknown;
      webkitSpeechRecognition?: unknown;
    };

    return Boolean(
      browserWindow.SpeechRecognition ??
        browserWindow.webkitSpeechRecognition
    );
  }, []);

  return {
    isListening,
    toggle,
    supported,
  };
}

// ─────────────────────────────────────────────────────────────────────────────
// Text-to-speech hook
// ─────────────────────────────────────────────────────────────────────────────

function useSpeech() {
  const speak = useCallback((text: string) => {
    if (!("speechSynthesis" in window)) {
      return;
    }

    window.speechSynthesis.cancel();

    // Remove markdown symbols before speaking.
    const clean = text
      .replace(/[\*\_#•]/g, "")
      .trim();

    if (!clean) {
      return;
    }

    const utterance = new SpeechSynthesisUtterance(clean);

    // Lightweight French detection.
    const isFrench = /[éèêëàâäùûüçîï]/i.test(clean);

    utterance.lang = isFrench ? "fr-FR" : "en-US";
    utterance.rate = 1.0;

    window.speechSynthesis.speak(utterance);
  }, []);

  const stop = useCallback(() => {
    if ("speechSynthesis" in window) {
      window.speechSynthesis.cancel();
    }
  }, []);

  return {
    speak,
    stop,
    supported: "speechSynthesis" in window,
  };
}

// ─────────────────────────────────────────────────────────────────────────────
// Draggable hook
// ─────────────────────────────────────────────────────────────────────────────

function useDraggable(initialPos: { x: number; y: number }) {
  const [pos, setPos] = useState(initialPos);

  const dragging = useRef(false);

  const origin = useRef({
    mx: 0,
    my: 0,
    wx: 0,
    wy: 0,
  });

  const moveRef = useRef<((event: MouseEvent) => void) | null>(null);
  const upRef = useRef<(() => void) | null>(null);

  const onMouseDown = useCallback(
    (e: React.MouseEvent) => {
      e.preventDefault();

      dragging.current = true;

      origin.current = {
        mx: e.clientX,
        my: e.clientY,
        wx: pos.x,
        wy: pos.y,
      };

      const move = (ev: MouseEvent) => {
        if (!dragging.current) {
          return;
        }

        setPos({
          x:
            origin.current.wx +
            (ev.clientX - origin.current.mx),

          y:
            origin.current.wy +
            (ev.clientY - origin.current.my),
        });
      };

      const up = () => {
        dragging.current = false;

        window.removeEventListener("mousemove", move);
        window.removeEventListener("mouseup", up);

        moveRef.current = null;
        upRef.current = null;
      };

      moveRef.current = move;
      upRef.current = up;

      window.addEventListener("mousemove", move);
      window.addEventListener("mouseup", up);
    },
    [pos]
  );

  useEffect(() => {
    return () => {
      if (moveRef.current) {
        window.removeEventListener(
          "mousemove",
          moveRef.current
        );
      }

      if (upRef.current) {
        window.removeEventListener(
          "mouseup",
          upRef.current
        );
      }
    };
  }, []);

  return {
    pos,
    onMouseDown,
  };
}

// ─────────────────────────────────────────────────────────────────────────────
// Main component
// ─────────────────────────────────────────────────────────────────────────────

const SprintAssistant = () => {
  const [open, setOpen] = useState(false);

  const [input, setInput] = useState("");

  const [messages, setMessages] = useState<Message[]>([]);

  const [thinking, setThinking] = useState(false);

  const [indexed, setIndexed] = useState(false);

  const [voiceModeOn, setVoiceModeOn] = useState(false);

  const scrollRef = useRef<HTMLDivElement>(null);

  const inputRef = useRef<HTMLInputElement>(null);

  const msgIdRef = useRef(0);

  // Prevent unnecessary duplicate indexing for the same project.
  const indexedProjectRef = useRef<number | null>(null);

  const { currentProject } = useProject();

  const pid = currentProject?.id ?? 0;

  // ───────────────────────────────────────────────────────────────────────────
  // Dashboard data
  // ───────────────────────────────────────────────────────────────────────────

  const ticketsQ = useTickets(pid);

  const blockersQ = useBlockers(pid);

  const devsQ = useDevelopers(pid);

  const sprintQ = useCurrentSprint(pid);

  const kpisQ = useSprintKpis(pid);

  // ───────────────────────────────────────────────────────────────────────────
  // Backend assistant
  //
  // IMPORTANT:
  // useAssistant does NOT receive conversation history.
  // Each question is sent independently.
  // ───────────────────────────────────────────────────────────────────────────

  const {
    sendMessage: sendToBackend,
    indexProjectData,
  } = useAssistant();

  const {
    speak,
    stop: stopSpeaking,
    supported: speechSupported,
  } = useSpeech();

  // ───────────────────────────────────────────────────────────────────────────
  // Prepare dashboard data
  // ───────────────────────────────────────────────────────────────────────────

  const tickets = useMemo(
    () => ticketsQ.data ?? [],
    [ticketsQ.data]
  );

  const blockers = useMemo(
    () => blockersQ.data ?? [],
    [blockersQ.data]
  );

  const rawDevs = useMemo(
    () => devsQ.data ?? [],
    [devsQ.data]
  );

  // ───────────────────────────────────────────────────────────────────────────
  // Enrich developers with ticket statistics
  // ───────────────────────────────────────────────────────────────────────────

  const developers: UIDeveloper[] = useMemo(
    () =>
      rawDevs.map((dev) => {
        const devTickets = tickets.filter(
          (ticket) => ticket.assigneeId === dev.id
        );

        const completed = devTickets.filter(
          (ticket) => ticket.status === "completed"
        );

        const blocked = devTickets.filter(
          (ticket) => ticket.status === "blocked"
        );

        const totalPts = devTickets.reduce(
          (sum, ticket) => sum + ticket.storyPoints,
          0
        );

        const donePts = completed.reduce(
          (sum, ticket) => sum + ticket.storyPoints,
          0
        );

        const status: UIDeveloper["status"] =
          blocked.length > 0
            ? "behind"
            : donePts / Math.max(totalPts, 1) < 0.4
              ? "at-risk"
              : "on-track";

        return {
          ...dev,
          completedPoints: donePts,
          totalPoints: totalPts,
          ticketsCompleted: completed.length,
          ticketsTotal: devTickets.length,
          blockers: blocked.length,
          status,
        };
      }),
    [rawDevs, tickets]
  );

  // ───────────────────────────────────────────────────────────────────────────
  // Determine whether dashboard data is ready
  // ───────────────────────────────────────────────────────────────────────────

  const dashboardDataReady = useMemo(() => {
    if (!currentProject) {
      return false;
    }

    const ticketsLoaded = !ticketsQ.isLoading;
    const blockersLoaded = !blockersQ.isLoading;
    const developersLoaded = !devsQ.isLoading;
    const sprintLoaded = !sprintQ.isLoading;
    const kpisLoaded = !kpisQ.isLoading;

    return (
      ticketsLoaded &&
      blockersLoaded &&
      developersLoaded &&
      sprintLoaded &&
      kpisLoaded
    );
  }, [
    currentProject,
    ticketsQ.isLoading,
    blockersQ.isLoading,
    devsQ.isLoading,
    sprintQ.isLoading,
    kpisQ.isLoading,
  ]);

  // ───────────────────────────────────────────────────────────────────────────
  // Index project data into ChromaDB
  //
  // Important:
  // - indexed = false while indexing
  // - indexed = true ONLY after indexProjectData succeeds
  // - same project is not repeatedly indexed unnecessarily
  // ───────────────────────────────────────────────────────────────────────────

  useEffect(() => {
    if (!currentProject) {
      setIndexed(false);
      indexedProjectRef.current = null;
      return;
    }

    if (!dashboardDataReady) {
      setIndexed(false);
      return;
    }

    if (
      indexedProjectRef.current === currentProject.id
    ) {
      setIndexed(true);
      return;
    }

    let cancelled = false;

    const runIndexing = async () => {
      try {
        setIndexed(false);

        console.log(
          `[ASSISTANT] Indexing project ${currentProject.id}...`
        );

        await indexProjectData({
          tickets,
          blockers,
          developers,
          sprint: sprintQ.data ?? undefined,
          kpis: kpisQ.data ?? undefined,
        });

        if (cancelled) {
          return;
        }

        indexedProjectRef.current = currentProject.id;

        setIndexed(true);

        console.log(
          `[ASSISTANT] Project ${currentProject.id} indexed successfully.`
        );
      } catch (error) {
        if (cancelled) {
          return;
        }

        indexedProjectRef.current = null;

        setIndexed(false);

        console.error(
          "[ASSISTANT] ChromaDB indexing failed:",
          error
        );
      }
    };

    void runIndexing();

    return () => {
      cancelled = true;
    };
  }, [
    currentProject?.id,
    dashboardDataReady,
    tickets,
    blockers,
    developers,
    sprintQ.data,
    kpisQ.data,
    indexProjectData,
  ]);

  // ───────────────────────────────────────────────────────────────────────────
  // Auto-scroll
  // ───────────────────────────────────────────────────────────────────────────

  useEffect(() => {
    scrollRef.current?.scrollTo({
      top: scrollRef.current.scrollHeight,
      behavior: "smooth",
    });
  }, [messages, thinking]);

  // ───────────────────────────────────────────────────────────────────────────
  // Focus input when opening
  // ───────────────────────────────────────────────────────────────────────────

  useEffect(() => {
    if (open) {
      const timer = window.setTimeout(() => {
        inputRef.current?.focus();
      }, 80);

      return () => {
        window.clearTimeout(timer);
      };
    }
  }, [open]);

  // ───────────────────────────────────────────────────────────────────────────
  // Dragging
  // ───────────────────────────────────────────────────────────────────────────

  const {
    pos: winPos,
    onMouseDown: onDragStart,
  } = useDraggable({
    x: 0,
    y: 0,
  });

  // ───────────────────────────────────────────────────────────────────────────
  // Add message
  // ───────────────────────────────────────────────────────────────────────────

  const addMessage = useCallback(
    (
      role: Message["role"],
      content: string
    ) => {
      setMessages((prev) => [
        ...prev,
        {
          id: `m${++msgIdRef.current}`,
          role,
          content,
          ts: Date.now(),
        },
      ]);
    },
    []
  );

  // ───────────────────────────────────────────────────────────────────────────
  // Export conversation locally
  //
  // No backend history is used.
  // This only exports messages currently displayed in the UI.
  // ───────────────────────────────────────────────────────────────────────────

  const exportConversation = useCallback(() => {
    if (messages.length === 0) {
      return;
    }

    const content = messages
      .map((message) => {
        const role =
          message.role === "user"
            ? "You"
            : "Sprint Assistant";

        return `[${role}]\n${message.content}`;
      })
      .join("\n\n");

    const blob = new Blob([content], {
      type: "text/plain;charset=utf-8",
    });

    const url = URL.createObjectURL(blob);

    const link = document.createElement("a");

    link.href = url;

    link.download = `sprint-assistant-${new Date()
      .toISOString()
      .slice(0, 10)}.txt`;

    document.body.appendChild(link);

    link.click();

    document.body.removeChild(link);

    URL.revokeObjectURL(url);
  }, [messages]);

  // ───────────────────────────────────────────────────────────────────────────
  // Send question
  // ───────────────────────────────────────────────────────────────────────────

  const handleSend = useCallback(
    async (text: string) => {
      const q = text.trim();

      if (!q) {
        return;
      }

      if (thinking) {
        return;
      }

      setInput("");

      addMessage("user", q);

      if (!currentProject) {
        addMessage(
          "assistant",
          "⚠️ Please select or import a project first so I can access your sprint data."
        );

        return;
      }

      if (!dashboardDataReady) {
        addMessage(
          "assistant",
          "⏳ Your dashboard data is still loading. Please wait a moment."
        );

        return;
      }

      if (!indexed) {
        addMessage(
          "assistant",
          "⏳ The project data is still being indexed. Please wait a moment."
        );

        return;
      }

      setThinking(true);

      try {
        console.log(
          `[ASSISTANT] Sending question: "${q}"`
        );

        const result = await sendToBackend(
          q,
          "auto"
        );

        if (!result || !result.answer) {
          throw new Error(
            "The assistant returned an empty answer."
          );
        }

        addMessage(
          "assistant",
          result.answer
        );

        if (voiceModeOn) {
          speak(result.answer);
        }
      } catch (error) {
        console.error(
          "[ASSISTANT] Request failed:",
          error
        );

        const errorMessage =
          error instanceof Error
            ? error.message
            : "Unable to reach the assistant backend.";

        addMessage(
          "assistant",
          `⚠️ ${errorMessage}`
        );
      } finally {
        setThinking(false);
      }
    },
    [
      thinking,
      addMessage,
      currentProject,
      dashboardDataReady,
      indexed,
      sendToBackend,
      voiceModeOn,
      speak,
    ]
  );

  // ───────────────────────────────────────────────────────────────────────────
  // Keyboard
  // ───────────────────────────────────────────────────────────────────────────

  const handleKeyDown = (
    e: KeyboardEvent<HTMLInputElement>
  ) => {
    if (
      e.key === "Enter" &&
      !e.shiftKey
    ) {
      e.preventDefault();

      void handleSend(input);
    }
  };

  // ───────────────────────────────────────────────────────────────────────────
  // Voice result
  // ───────────────────────────────────────────────────────────────────────────

  const handleVoiceResult = useCallback(
    (text: string) => {
      if (!text.trim()) {
        return;
      }

      setInput(text);

      window.setTimeout(() => {
        void handleSend(text);
      }, 300);
    },
    [handleSend]
  );

  const {
    isListening,
    toggle: toggleVoice,
    supported: voiceSupported,
  } = useVoiceInput(handleVoiceResult);

  // ───────────────────────────────────────────────────────────────────────────
  // Other actions
  // ───────────────────────────────────────────────────────────────────────────

  const handleSuggestion = (question: string) => {
    void handleSend(question);
  };

  const clearChat = () => {
    setMessages([]);
  };

  const dataReady =
    indexed &&
    !!currentProject &&
    dashboardDataReady;

  // ───────────────────────────────────────────────────────────────────────────
  // Render
  // ───────────────────────────────────────────────────────────────────────────

  return (
    <>
      {/* Floating action button */}

      <motion.button
        onClick={() => setOpen((value) => !value)}
        whileHover={{ scale: 1.08 }}
        whileTap={{ scale: 0.95 }}
        className={cn(
          "fixed bottom-6 right-6 z-50 flex h-14 w-14",
          "items-center justify-center rounded-full shadow-lg",
          "transition-colors",
          open
            ? "bg-foreground text-background"
            : "bg-primary text-primary-foreground"
        )}
        aria-label="Open AI Assistant"
      >
        <AnimatePresence
          mode="wait"
          initial={false}
        >
          {open ? (
            <motion.span
              key="x"
              initial={{
                rotate: -90,
                opacity: 0,
              }}
              animate={{
                rotate: 0,
                opacity: 1,
              }}
              exit={{
                rotate: 90,
                opacity: 0,
              }}
              transition={{
                duration: 0.15,
              }}
            >
              <X className="h-6 w-6" />
            </motion.span>
          ) : (
            <motion.span
              key="bot"
              initial={{
                rotate: 90,
                opacity: 0,
              }}
              animate={{
                rotate: 0,
                opacity: 1,
              }}
              exit={{
                rotate: -90,
                opacity: 0,
              }}
              transition={{
                duration: 0.15,
              }}
            >
              <Sparkles className="h-6 w-6" />
            </motion.span>
          )}
        </AnimatePresence>

        {!open && dataReady && (
          <span
            className="
              absolute -top-0.5 -right-0.5
              h-3 w-3 rounded-full
              border-2 border-background
              bg-emerald-500
            "
          />
        )}
      </motion.button>

      {/* Chat window */}

      <AnimatePresence>
        {open && (
          <motion.div
            initial={{
              opacity: 0,
              y: 24,
              scale: 0.95,
            }}
            animate={{
              opacity: 1,
              y: 0,
              scale: 1,
            }}
            exit={{
              opacity: 0,
              y: 24,
              scale: 0.95,
            }}
            transition={{
              type: "spring",
              stiffness: 340,
              damping: 28,
            }}
            style={{
              position: "fixed",
              bottom: "88px",
              right: "24px",
              transform: `translate(${winPos.x}px, ${winPos.y}px)`,
              zIndex: 50,
            }}
            className="
              flex flex-col
              w-[380px]
              max-h-[580px]
              rounded-2xl
              border border-border
              bg-card
              shadow-2xl
              overflow-hidden
            "
          >
            {/* Header */}

            <div
              onMouseDown={onDragStart}
              className="
                flex items-center gap-2.5
                border-b border-border
                bg-card
                px-4 py-3
                cursor-grab
                active:cursor-grabbing
                select-none
              "
            >
              <div
                className="
                  flex h-8 w-8 shrink-0
                  items-center justify-center
                  rounded-lg
                  bg-primary/15
                "
              >
                <Bot className="h-4.5 w-4.5 text-primary" />
              </div>

              <div className="flex-1 min-w-0">
                <p className="text-sm font-semibold text-foreground leading-none">
                  Sprint Assistant
                </p>

                <p className="text-[11px] text-muted-foreground mt-0.5">
                  {dataReady
                    ? `${tickets.length} tickets · ${blockers.length} blockers · ${developers.length} devs indexed`
                    : "Loading data…"}
                </p>
              </div>

              <div className="flex items-center gap-1">
                {/* Voice output */}

                {speechSupported && (
                  <button
                    onMouseDown={(e) =>
                      e.stopPropagation()
                    }
                    onClick={() => {
                      setVoiceModeOn((value) => {
                        if (value) {
                          stopSpeaking();
                        }

                        return !value;
                      });
                    }}
                    title={
                      voiceModeOn
                        ? "Turn off spoken answers"
                        : "Turn on spoken answers"
                    }
                    className={cn(
                      "rounded-md p-1.5",
                      "transition-colors",
                      voiceModeOn
                        ? "text-primary bg-primary/15"
                        : "text-muted-foreground hover:text-foreground hover:bg-muted"
                    )}
                  >
                    {voiceModeOn ? (
                      <Volume2 className="h-3.5 w-3.5" />
                    ) : (
                      <VolumeX className="h-3.5 w-3.5" />
                    )}
                  </button>
                )}

                {/* Export */}

                <button
                  onMouseDown={(e) =>
                    e.stopPropagation()
                  }
                  onClick={exportConversation}
                  title="Export conversation"
                  disabled={messages.length === 0}
                  className="
                    rounded-md p-1.5
                    text-muted-foreground
                    hover:text-foreground
                    hover:bg-muted
                    transition-colors
                    disabled:opacity-30
                    disabled:hover:bg-transparent
                  "
                >
                  <Download className="h-3.5 w-3.5" />
                </button>

                {/* Clear */}

                <button
                  onMouseDown={(e) =>
                    e.stopPropagation()
                  }
                  onClick={clearChat}
                  title="Clear chat"
                  className="
                    rounded-md p-1.5
                    text-muted-foreground
                    hover:text-foreground
                    hover:bg-muted
                    transition-colors
                  "
                >
                  <RotateCcw className="h-3.5 w-3.5" />
                </button>

                <GripVertical className="h-4 w-4 text-muted-foreground/40" />
              </div>
            </div>

            {/* Messages */}

            <div
              ref={scrollRef}
              className="
                flex-1
                overflow-y-auto
                px-4 py-4
                space-y-3
                min-h-0
              "
            >
              {/* Empty state */}

              {messages.length === 0 &&
                !thinking && (
                  <div className="space-y-4">
                    <div className="flex gap-2.5">
                      <div
                        className="
                          flex h-7 w-7 shrink-0
                          items-center justify-center
                          rounded-full
                          bg-primary/15
                          mt-0.5
                        "
                      >
                        <Bot className="h-3.5 w-3.5 text-primary" />
                      </div>

                      <div
                        className="
                          rounded-2xl
                          rounded-tl-sm
                          bg-muted
                          px-3.5 py-3
                          text-sm
                          text-foreground
                          max-w-[280px]
                        "
                      >
                        {dataReady
                          ? `Hi! I've indexed your ${currentProject?.name} project data. Ask me anything about tickets, blockers, developers, or sprint performance.`
                          : "Hi! I'm loading your project data. Select a project to get started."}
                      </div>
                    </div>

                    {dataReady && (
                      <div className="space-y-1.5">
                        <p className="text-[11px] text-muted-foreground px-1">
                          Suggestions:
                        </p>

                        <div className="flex flex-col gap-1.5">
                          {SUGGESTIONS.map(
                            (suggestion) => (
                              <button
                                key={suggestion}
                                onClick={() =>
                                  handleSuggestion(
                                    suggestion
                                  )
                                }
                                disabled={thinking}
                                className="
                                  flex items-center
                                  justify-between
                                  rounded-xl
                                  border border-border
                                  bg-background/50
                                  px-3 py-2
                                  text-xs text-left
                                  text-muted-foreground
                                  hover:border-primary/40
                                  hover:text-foreground
                                  hover:bg-primary/5
                                  transition-all
                                  group
                                  disabled:opacity-50
                                "
                              >
                                {suggestion}

                                <ChevronRight
                                  className="
                                    h-3 w-3
                                    shrink-0
                                    opacity-0
                                    group-hover:opacity-100
                                    transition-opacity
                                  "
                                />
                              </button>
                            )
                          )}
                        </div>
                      </div>
                    )}
                  </div>
                )}

              {/* Messages */}

              {messages.map((message) => (
                <div
                  key={message.id}
                  className={cn(
                    "flex gap-2.5",
                    message.role === "user" &&
                      "flex-row-reverse"
                  )}
                >
                  {message.role === "assistant" && (
                    <div
                      className="
                        flex h-7 w-7 shrink-0
                        items-center justify-center
                        rounded-full
                        bg-primary/15
                        mt-0.5
                      "
                    >
                      <Bot className="h-3.5 w-3.5 text-primary" />
                    </div>
                  )}

                  <div
                    className={cn(
                      "rounded-2xl",
                      "px-3.5 py-2.5",
                      "text-sm",
                      "max-w-[280px]",
                      "leading-relaxed",

                      message.role === "user"
                        ? "rounded-tr-sm bg-primary text-primary-foreground"
                        : "rounded-tl-sm bg-muted text-foreground"
                    )}
                  >
                    {message.role === "assistant" ? (
                      <div className="space-y-0.5">
                        {renderMarkdown(
                          message.content
                        )}
                      </div>
                    ) : (
                      message.content
                    )}
                  </div>
                </div>
              ))}

              {/* Thinking */}

              {thinking && (
                <div className="flex gap-2.5">
                  <div
                    className="
                      flex h-7 w-7 shrink-0
                      items-center justify-center
                      rounded-full
                      bg-primary/15
                    "
                  >
                    <Loader2 className="h-3.5 w-3.5 text-primary animate-spin" />
                  </div>

                  <div
                    className="
                      rounded-2xl
                      rounded-tl-sm
                      bg-muted
                      px-3.5 py-3
                    "
                  >
                    <div className="flex items-center gap-1.5">
                      <span
                        className="
                          h-1.5 w-1.5
                          rounded-full
                          bg-muted-foreground/60
                          animate-bounce
                        "
                      />

                      <span
                        className="
                          h-1.5 w-1.5
                          rounded-full
                          bg-muted-foreground/60
                          animate-bounce
                          [animation-delay:150ms]
                        "
                      />

                      <span
                        className="
                          h-1.5 w-1.5
                          rounded-full
                          bg-muted-foreground/60
                          animate-bounce
                          [animation-delay:300ms]
                        "
                      />
                    </div>
                  </div>
                </div>
              )}
            </div>

            {/* Voice listening overlay */}

            <AnimatePresence>
              {isListening && (
                <motion.div
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  exit={{ opacity: 0 }}
                  className="
                    absolute inset-0
                    flex flex-col
                    items-center justify-center
                    bg-card/95
                    backdrop-blur-sm
                    rounded-2xl
                    z-10
                  "
                >
                  <motion.div
                    animate={{
                      scale: [1, 1.15, 1],
                    }}
                    transition={{
                      repeat: Infinity,
                      duration: 1.2,
                    }}
                    className="
                      flex h-16 w-16
                      items-center justify-center
                      rounded-full
                      bg-rose-500/15
                      ring-4
                      ring-rose-500/25
                    "
                  >
                    <Mic className="h-7 w-7 text-rose-500" />
                  </motion.div>

                  <p className="mt-4 text-sm font-semibold text-foreground">
                    Listening…
                  </p>

                  <p className="mt-1 text-xs text-muted-foreground">
                    Speak your question clearly
                  </p>

                  <button
                    onClick={toggleVoice}
                    className="
                      mt-5
                      rounded-full
                      border border-border
                      px-4 py-1.5
                      text-xs
                      text-muted-foreground
                      hover:text-foreground
                      transition-colors
                    "
                  >
                    Cancel
                  </button>
                </motion.div>
              )}
            </AnimatePresence>

            {/* Input */}

            <div
              className="
                border-t border-border
                bg-card
                px-3 py-3
              "
            >
              <div className="flex items-center gap-2">
                {/* Voice input */}

                {voiceSupported && (
                  <button
                    onClick={toggleVoice}
                    disabled={
                      thinking ||
                      !dataReady
                    }
                    title={
                      isListening
                        ? "Stop listening"
                        : "Voice input"
                    }
                    className={cn(
                      "flex h-9 w-9 shrink-0",
                      "items-center justify-center",
                      "rounded-xl",
                      "transition-colors",

                      isListening
                        ? "bg-rose-500 text-white"
                        : "bg-muted text-muted-foreground hover:text-foreground",

                      "disabled:opacity-50"
                    )}
                  >
                    {isListening ? (
                      <MicOff className="h-4 w-4" />
                    ) : (
                      <Mic className="h-4 w-4" />
                    )}
                  </button>
                )}

                {/* Text input */}

                <input
                  ref={inputRef}
                  value={input}
                  onChange={(
                    e: ChangeEvent<HTMLInputElement>
                  ) =>
                    setInput(e.target.value)
                  }
                  onKeyDown={handleKeyDown}
                  placeholder={
                    dataReady
                      ? "Ask about tickets, blockers, sprint…"
                      : "Loading project data…"
                  }
                  disabled={
                    thinking ||
                    isListening ||
                    !dataReady
                  }
                  className="
                    flex-1
                    rounded-xl
                    border border-border
                    bg-muted/50
                    px-3.5 py-2
                    text-sm
                    text-foreground
                    placeholder:text-muted-foreground

                    focus:outline-none
                    focus:ring-2
                    focus:ring-primary/30
                    focus:border-primary/50

                    disabled:opacity-50
                  "
                />

                {/* Send */}

                <button
                  onClick={() =>
                    void handleSend(input)
                  }
                  disabled={
                    !input.trim() ||
                    thinking ||
                    !dataReady
                  }
                  className={cn(
                    "flex h-9 w-9 shrink-0",
                    "items-center justify-center",
                    "rounded-xl",
                    "transition-colors",

                    input.trim() &&
                      !thinking &&
                      dataReady
                      ? "bg-primary text-primary-foreground hover:bg-primary/90"
                      : "bg-muted text-muted-foreground cursor-not-allowed"
                  )}
                >
                  <Send className="h-4 w-4" />
                </button>
              </div>

              <p className="mt-2 text-center text-[10px] text-muted-foreground/50">
                Retrieval-augmented · Gemini-powered answers
              </p>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </>
  );
};

export default SprintAssistant;

